export interface AppConfig {
  port: number;
  authRefreshWindowSeconds: number;
  notesSyncBatchSize: number;
}

export interface SessionSummary {
  sessionId: string;
  userId: string;
  workspaceIds: string[];
  refreshedAt: string;
}

export type WorkspacePermission = 'notes:read' | 'notes:write';

export interface PermissionDecision {
  allowed: boolean;
  scope: WorkspacePermission;
  reason: string;
}

import { MemoryCache } from './cache.js';
import type { AppConfig, SessionSummary } from './types.js';

export function createSessionCache(
  config: AppConfig,
): MemoryCache<string, SessionSummary> {
  return new MemoryCache<string, SessionSummary>({
    ttlMs: config.authRefreshWindowSeconds * 1000,
  });
}

import { MemoryCache } from './cache.js';
import type { AppConfig, PermissionDecision } from './types.js';

export function createPermissionCache(
  config: AppConfig,
): MemoryCache<string, PermissionDecision> {
  return new MemoryCache<string, PermissionDecision>({
    ttlMs: config.authRefreshWindowSeconds * 1000,
  });
}

import { readFileSync } from 'node:fs';
import path from 'node:path';
import type { AppConfig } from './lib/types.js';

function loadDefaults() {
  const defaultsPath = path.resolve(
    process.cwd(),
    'packages',
    'config',
    'defaults.json',
  );

  return JSON.parse(readFileSync(defaultsPath, 'utf8')) as Record<string, number>;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const defaults = loadDefaults();

  return {
    port: env.PORT ? Number(env.PORT) : defaults.port,
    authRefreshWindowSeconds: env.AUTH_REFRESH_WINDOW_SECONDS
      ? Number(env.AUTH_REFRESH_WINDOW_SECONDS)
      : defaults.authRefreshWindowSeconds,
    notesSyncBatchSize: defaults.notesSyncBatchSize,
  };
}
